=== FILE: axi4_lite_regs.v ===
`timescale 1ns / 1ps
`default_nettype none

// axi4_lite_regs: four 32-bit read/write registers behind an AXI4-Lite
// subordinate port. Implements interface_spec.md per microarchitecture.md:
// holding registers for AW and W, READY a function of state only, one
// outstanding transaction per direction, SLVERR for unmapped addresses,
// synchronous active-low reset, 1-cycle response latency.
module axi4_lite_regs #(
    parameter ADDR_WIDTH = 4,
    parameter DATA_WIDTH = 32
) (
    input  wire                    aclk,
    input  wire                    aresetn,
    input  wire [ADDR_WIDTH-1:0]   s_axil_awaddr,
    input  wire                    s_axil_awvalid,
    output wire                    s_axil_awready,
    input  wire [DATA_WIDTH-1:0]   s_axil_wdata,
    input  wire [DATA_WIDTH/8-1:0] s_axil_wstrb,
    input  wire                    s_axil_wvalid,
    output wire                    s_axil_wready,
    output wire [1:0]              s_axil_bresp,
    output wire                    s_axil_bvalid,
    input  wire                    s_axil_bready,
    input  wire [ADDR_WIDTH-1:0]   s_axil_araddr,
    input  wire                    s_axil_arvalid,
    output wire                    s_axil_arready,
    output wire [DATA_WIDTH-1:0]   s_axil_rdata,
    output wire [1:0]              s_axil_rresp,
    output wire                    s_axil_rvalid,
    input  wire                    s_axil_rready
);

  localparam STRB_WIDTH = DATA_WIDTH / 8;
  localparam [1:0] RESP_OKAY   = 2'b00;
  localparam [1:0] RESP_SLVERR = 2'b10;

  // ---------------------------------------------------------------------
  // State
  // ---------------------------------------------------------------------
  // Control state (reset)
  reg                  aw_held;
  reg                  w_held;
  reg                  bvalid_q;
  reg [1:0]            bresp_q;
  reg                  rvalid_q;
  reg [1:0]            rresp_q;
  reg [DATA_WIDTH-1:0] rdata_q;
  reg [DATA_WIDTH-1:0] reg0;
  reg [DATA_WIDTH-1:0] reg1;
  reg [DATA_WIDTH-1:0] reg2;
  reg [DATA_WIDTH-1:0] reg3;
  // Holding registers (datapath, not reset; qualified by aw_held / w_held)
  reg [ADDR_WIDTH-1:0] aw_addr_q;
  reg [DATA_WIDTH-1:0] w_data_q;
  reg [STRB_WIDTH-1:0] w_strb_q;

  // ---------------------------------------------------------------------
  // Handshakes: READY depends on state only (no VALID -> READY path)
  // ---------------------------------------------------------------------
  assign s_axil_awready = !aw_held && !bvalid_q;
  assign s_axil_wready  = !w_held  && !bvalid_q;
  assign s_axil_arready = !rvalid_q;

  wire aw_hs = s_axil_awvalid && s_axil_awready;
  wire w_hs  = s_axil_wvalid  && s_axil_wready;
  wire ar_hs = s_axil_arvalid && s_axil_arready;

  // The write fires on the edge that completes the AW/W pair.
  wire do_write = (aw_held || aw_hs) && (w_held || w_hs);

  wire [ADDR_WIDTH-1:0] wr_addr = aw_held ? aw_addr_q : s_axil_awaddr;
  wire [DATA_WIDTH-1:0] wr_data = w_held  ? w_data_q  : s_axil_wdata;
  wire [STRB_WIDTH-1:0] wr_strb = w_held  ? w_strb_q  : s_axil_wstrb;

  // ---------------------------------------------------------------------
  // Byte-enable mask: strobe bit n enables bits 8n+7:8n
  // ---------------------------------------------------------------------
  wire [DATA_WIDTH-1:0] wr_mask;
  genvar g;
  generate
    for (g = 0; g < STRB_WIDTH; g = g + 1) begin : g_wr_mask
      assign wr_mask[8*g +: 8] = {8{wr_strb[g]}};
    end
  endgenerate

  // ---------------------------------------------------------------------
  // Address decode: mapped when word aligned and no bits above bit 3
  // ---------------------------------------------------------------------
  wire wr_hi_zero;
  wire rd_hi_zero;
  generate
    if (ADDR_WIDTH > 4) begin : g_addr_hi
      assign wr_hi_zero = (wr_addr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
      assign rd_hi_zero = (s_axil_araddr[ADDR_WIDTH-1:4] == {(ADDR_WIDTH-4){1'b0}});
    end else begin : g_addr_no_hi
      assign wr_hi_zero = 1'b1;
      assign rd_hi_zero = 1'b1;
    end
  endgenerate

  wire       wr_mapped = (wr_addr[1:0] == 2'b00) && wr_hi_zero;
  wire [1:0] wr_idx    = wr_addr[3:2];
  wire       rd_mapped = (s_axil_araddr[1:0] == 2'b00) && rd_hi_zero;
  wire [1:0] rd_idx    = s_axil_araddr[3:2];

  // ---------------------------------------------------------------------
  // Register file next state
  // ---------------------------------------------------------------------
  wire we0 = do_write && wr_mapped && (wr_idx == 2'd0);
  wire we1 = do_write && wr_mapped && (wr_idx == 2'd1);
  wire we2 = do_write && wr_mapped && (wr_idx == 2'd2);
  wire we3 = do_write && wr_mapped && (wr_idx == 2'd3);

  wire [DATA_WIDTH-1:0] reg0_d = we0 ? ((reg0 & ~wr_mask) | (wr_data & wr_mask)) : reg0;
  wire [DATA_WIDTH-1:0] reg1_d = we1 ? ((reg1 & ~wr_mask) | (wr_data & wr_mask)) : reg1;
  wire [DATA_WIDTH-1:0] reg2_d = we2 ? ((reg2 & ~wr_mask) | (wr_data & wr_mask)) : reg2;
  wire [DATA_WIDTH-1:0] reg3_d = we3 ? ((reg3 & ~wr_mask) | (wr_data & wr_mask)) : reg3;

  // ---------------------------------------------------------------------
  // Write channel next state
  // ---------------------------------------------------------------------
  wire aw_held_d = do_write ? 1'b0 : (aw_hs ? 1'b1 : aw_held);
  wire w_held_d  = do_write ? 1'b0 : (w_hs  ? 1'b1 : w_held);

  wire [ADDR_WIDTH-1:0] aw_addr_d = (aw_hs && !do_write) ? s_axil_awaddr : aw_addr_q;
  wire [DATA_WIDTH-1:0] w_data_d  = (w_hs  && !do_write) ? s_axil_wdata  : w_data_q;
  wire [STRB_WIDTH-1:0] w_strb_d  = (w_hs  && !do_write) ? s_axil_wstrb  : w_strb_q;

  wire       bvalid_d = do_write ? 1'b1 :
                        ((bvalid_q && s_axil_bready) ? 1'b0 : bvalid_q);
  wire [1:0] bresp_d  = do_write ? (wr_mapped ? RESP_OKAY : RESP_SLVERR) : bresp_q;

  // ---------------------------------------------------------------------
  // Read channel next state
  // ---------------------------------------------------------------------
  wire [DATA_WIDTH-1:0] rd_sel = (rd_idx == 2'd0) ? reg0 :
                                 (rd_idx == 2'd1) ? reg1 :
                                 (rd_idx == 2'd2) ? reg2 : reg3;

  wire                  rvalid_d = ar_hs ? 1'b1 :
                                   ((rvalid_q && s_axil_rready) ? 1'b0 : rvalid_q);
  wire [1:0]            rresp_d  = ar_hs ? (rd_mapped ? RESP_OKAY : RESP_SLVERR) : rresp_q;
  wire [DATA_WIDTH-1:0] rdata_d  = ar_hs ? (rd_mapped ? rd_sel : {DATA_WIDTH{1'b0}}) : rdata_q;

  // ---------------------------------------------------------------------
  // Registers
  // ---------------------------------------------------------------------
  always @(posedge aclk) begin
    if (!aresetn) begin
      aw_held  <= 1'b0;
      w_held   <= 1'b0;
      bvalid_q <= 1'b0;
      bresp_q  <= RESP_OKAY;
      rvalid_q <= 1'b0;
      rresp_q  <= RESP_OKAY;
      rdata_q  <= {DATA_WIDTH{1'b0}};
      reg0     <= {DATA_WIDTH{1'b0}};
      reg1     <= {DATA_WIDTH{1'b0}};
      reg2     <= {DATA_WIDTH{1'b0}};
      reg3     <= {DATA_WIDTH{1'b0}};
    end else begin
      aw_held  <= aw_held_d;
      w_held   <= w_held_d;
      bvalid_q <= bvalid_d;
      bresp_q  <= bresp_d;
      rvalid_q <= rvalid_d;
      rresp_q  <= rresp_d;
      rdata_q  <= rdata_d;
      reg0     <= reg0_d;
      reg1     <= reg1_d;
      reg2     <= reg2_d;
      reg3     <= reg3_d;
    end
  end

  // Datapath holding registers: no reset (qualified by the held flags).
  always @(posedge aclk) begin
    aw_addr_q <= aw_addr_d;
    w_data_q  <= w_data_d;
    w_strb_q  <= w_strb_d;
  end

  assign s_axil_bvalid = bvalid_q;
  assign s_axil_bresp  = bresp_q;
  assign s_axil_rvalid = rvalid_q;
  assign s_axil_rresp  = rresp_q;
  assign s_axil_rdata  = rdata_q;

`ifdef FORMAL
  // ---------------------------------------------------------------------
  // Design-intent properties (handshake rules, microarchitecture 7)
  // ---------------------------------------------------------------------
  reg f_past_valid;
  initial f_past_valid = 1'b0;
  always @(posedge aclk) f_past_valid <= 1'b1;

  // Reset is active on the first cycle.
  always @(*) if (!f_past_valid) assume(!aresetn);

  // Manager: VALID low during reset (interface spec 7).
  always @(*) if (!aresetn) assume(!s_axil_awvalid && !s_axil_wvalid && !s_axil_arvalid);

  // Manager: VALID and payload hold until READY.
  always @(posedge aclk) begin
    if (f_past_valid && $past(aresetn) && aresetn) begin
      if ($past(s_axil_awvalid && !s_axil_awready))
        assume(s_axil_awvalid && $stable(s_axil_awaddr));
      if ($past(s_axil_wvalid && !s_axil_wready))
        assume(s_axil_wvalid && $stable(s_axil_wdata) && $stable(s_axil_wstrb));
      if ($past(s_axil_arvalid && !s_axil_arready))
        assume(s_axil_arvalid && $stable(s_axil_araddr));
    end
  end

  always @(posedge aclk) begin
    // Responses low after reset; half-accepted write discarded.
    if (f_past_valid && !$past(aresetn)) begin
      assert(!s_axil_bvalid);
      assert(!s_axil_rvalid);
      assert(!aw_held);
      assert(!w_held);
    end
    if (f_past_valid && $past(aresetn)) begin
      // B and R hold, with a stable payload, until taken.
      if ($past(s_axil_bvalid && !s_axil_bready))
        assert(s_axil_bvalid && $stable(s_axil_bresp));
      if ($past(s_axil_rvalid && !s_axil_rready))
        assert(s_axil_rvalid && $stable(s_axil_rresp) && $stable(s_axil_rdata));
      // A response appears only after an accepted request, one cycle later.
      if (s_axil_bvalid && !$past(s_axil_bvalid))
        assert($past(do_write));
      if (s_axil_rvalid && !$past(s_axil_rvalid))
        assert($past(ar_hs));
      // Response codes follow the address policy.
      if ($past(do_write))
        assert(s_axil_bvalid && (s_axil_bresp == ($past(wr_mapped) ? RESP_OKAY : RESP_SLVERR)));
      if ($past(ar_hs))
        assert(s_axil_rvalid && (s_axil_rresp == ($past(rd_mapped) ? RESP_OKAY : RESP_SLVERR)));
    end
  end

  // At most one write open; no held half-write while B is pending.
  always @(*) begin
    if (f_past_valid) begin
      assert(!(aw_held && w_held));
      if (s_axil_bvalid) assert(!aw_held && !w_held);
      if (s_axil_bvalid) assert((s_axil_bresp == RESP_OKAY) || (s_axil_bresp == RESP_SLVERR));
      if (s_axil_rvalid) assert((s_axil_rresp == RESP_OKAY) || (s_axil_rresp == RESP_SLVERR));
      if (s_axil_rvalid && (s_axil_rresp == RESP_SLVERR))
        assert(s_axil_rdata == {DATA_WIDTH{1'b0}});
    end
  end

  always @(posedge aclk) begin
    if (f_past_valid && aresetn) begin
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_OKAY));
      cover(s_axil_bvalid && s_axil_bready && (s_axil_bresp == RESP_SLVERR));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_OKAY));
      cover(s_axil_rvalid && s_axil_rready && (s_axil_rresp == RESP_SLVERR));
    end
  end
`endif

endmodule

`default_nettype wire
=== END FILE ===
=== FILE: axi4_lite_regs_tb.v ===
`timescale 1ns / 1ps
`default_nettype none

`define CHECK(COND, MSG) \
  begin \
    if (COND) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("FAIL: %s (t=%0t)", MSG, $time); \
    end \
  end

`define CHECK_EQ(ACT, EXP, MSG) \
  begin \
    if ((ACT) === (EXP)) passed = passed + 1; \
    else begin \
      failed = failed + 1; \
      $error("FAIL: %s: got 0x%0h, wanted 0x%0h (t=%0t)", MSG, (ACT), (EXP), $time); \
    end \
  end

module axi4_lite_regs_tb;

  localparam [1:0] OKAY   = 2'b00;
  localparam [1:0] SLVERR = 2'b10;

  reg         aclk    = 1'b0;
  reg         aresetn = 1'b0;
  reg  [3:0]  awaddr  = 4'h0;
  reg         awvalid = 1'b0;
  wire        awready;
  reg  [31:0] wdata   = 32'h0000_0000;
  reg  [3:0]  wstrb   = 4'h0;
  reg         wvalid  = 1'b0;
  wire        wready;
  wire [1:0]  bresp;
  wire        bvalid;
  reg         bready  = 1'b0;
  reg  [3:0]  araddr  = 4'h0;
  reg         arvalid = 1'b0;
  wire        arready;
  wire [31:0] rdata;
  wire [1:0]  rresp;
  wire        rvalid;
  reg         rready  = 1'b0;

  integer passed = 0;
  integer failed = 0;
  integer w_accept_cycles = 0;
  integer r_accept_cycles = 0;
  reg     finished = 1'b0;
  reg [8*64-1:0] nonce = {(8*64){1'b0}};
  reg [31:0] model [0:3];

  axi4_lite_regs #(
    .ADDR_WIDTH(4),
    .DATA_WIDTH(32)
  ) dut (
    .aclk           (aclk),
    .aresetn        (aresetn),
    .s_axil_awaddr  (awaddr),
    .s_axil_awvalid (awvalid),
    .s_axil_awready (awready),
    .s_axil_wdata   (wdata),
    .s_axil_wstrb   (wstrb),
    .s_axil_wvalid  (wvalid),
    .s_axil_wready  (wready),
    .s_axil_bresp   (bresp),
    .s_axil_bvalid  (bvalid),
    .s_axil_bready  (bready),
    .s_axil_araddr  (araddr),
    .s_axil_arvalid (arvalid),
    .s_axil_arready (arready),
    .s_axil_rdata   (rdata),
    .s_axil_rresp   (rresp),
    .s_axil_rvalid  (rvalid),
    .s_axil_rready  (rready)
  );

  // Clock: rising edges at 5, 15, 25, ...; falling edges at 10, 20, ...
  always #5 aclk = ~aclk;

  // Mapped when word aligned (ADDR_WIDTH 4 has no higher bits).
  function addr_mapped;
    input [1:0] lo;
    begin
      addr_mapped = (lo == 2'b00);
    end
  endfunction

  function [31:0] merge32;
    input [31:0] old_v;
    input [31:0] new_v;
    input [3:0]  strb;
    reg   [31:0] mask;
    begin
      mask    = {{8{strb[3]}}, {8{strb[2]}}, {8{strb[1]}}, {8{strb[0]}}};
      merge32 = (old_v & ~mask) | (new_v & mask);
    end
  endfunction

  task reset_model;
    begin
      model[0] = 32'h0000_0000;
      model[1] = 32'h0000_0000;
      model[2] = 32'h0000_0000;
      model[3] = 32'h0000_0000;
    end
  endtask

  // Reset with all manager VALIDs low; checks responses during and after.
  task apply_reset;
    input integer cycles;
    begin
      @(negedge aclk);
      awvalid = 1'b0;
      wvalid  = 1'b0;
      arvalid = 1'b0;
      bready  = 1'b0;
      rready  = 1'b0;
      aresetn = 1'b0;
      repeat (cycles) @(posedge aclk);
      #4;
      `CHECK_EQ(bvalid, 1'b0, "reset: BVALID low during reset")
      `CHECK_EQ(rvalid, 1'b0, "reset: RVALID low during reset")
      @(negedge aclk);
      aresetn = 1'b1;
      reset_model;
      #4;
      `CHECK_EQ(bvalid,  1'b0, "reset: BVALID low after reset")
      `CHECK_EQ(rvalid,  1'b0, "reset: RVALID low after reset")
      `CHECK_EQ(awready, 1'b1, "reset: AWREADY high after reset")
      `CHECK_EQ(wready,  1'b1, "reset: WREADY high after reset")
      `CHECK_EQ(arready, 1'b1, "reset: ARREADY high after reset")
      @(posedge aclk);
    end
  endtask

  // Write: AW raised after aw_dly cycles, W after w_dly cycles,
  // BREADY held low for b_dly cycles after the write completes.
  task axil_write;
    input [3:0]   addr;
    input [31:0]  data;
    input [3:0]   strb;
    input integer aw_dly;
    input integer w_dly;
    input integer b_dly;
    integer t;
    integer n;
    integer first_n;
    reg aw_done;
    reg w_done;
    reg aw_hs;
    reg w_hs;
    reg got;
    reg [1:0] exp_resp;
    reg [1:0] held_resp;
    begin
      exp_resp  = addr_mapped(addr[1:0]) ? OKAY : SLVERR;
      held_resp = 2'b00;
      aw_done   = 1'b0;
      w_done    = 1'b0;
      t = 0;
      while (!(aw_done && w_done)) begin
        @(negedge aclk);
        awvalid = !aw_done && (t >= aw_dly);
        awaddr  = addr;
        wvalid  = !w_done && (t >= w_dly);
        wdata   = data;
        wstrb   = strb;
        bready  = 1'b0;
        #4;
        aw_hs = awvalid && awready;
        w_hs  = wvalid && wready;
        `CHECK_EQ(bvalid, 1'b0, "write: no B before both AW and W are accepted")
        @(posedge aclk);
        aw_done = aw_done || aw_hs;
        w_done  = w_done || w_hs;
        t = t + 1;
        if (!(aw_done && w_done) && (t > 50)) begin
          `CHECK(1'b0, "write: AW and W not accepted within 50 cycles")
          aw_done = 1'b1;
          w_done  = 1'b1;
        end
      end
      w_accept_cycles = t;
      if (exp_resp == OKAY)
        model[addr[3:2]] = merge32(model[addr[3:2]], data, strb);

      n = 0;
      first_n = 0;
      got = 1'b0;
      while (!got) begin
        @(negedge aclk);
        n = n + 1;
        awvalid = 1'b0;
        wvalid  = 1'b0;
        bready  = (n > b_dly);
        #4;
        if (bvalid) begin
          if (first_n == 0) begin
            first_n   = n;
            held_resp = bresp;
            `CHECK_EQ(bresp, exp_resp, "write: BRESP")
          end else begin
            `CHECK_EQ(bresp, held_resp, "write: BRESP holds while B waits")
          end
          `CHECK_EQ(awready, 1'b0, "write: AW not accepted while B is pending")
          `CHECK_EQ(wready,  1'b0, "write: W not accepted while B is pending")
          if (bready) got = 1'b1;
        end else if (first_n != 0) begin
          `CHECK(1'b0, "write: BVALID dropped before BREADY")
          got = 1'b1;
        end
        @(posedge aclk);
        if (!got && (n > 50)) begin
          `CHECK(1'b0, "write: no B within 50 cycles")
          got = 1'b1;
        end
      end
      `CHECK((first_n >= 1) && (first_n <= 2), "write: B latency at most 2 cycles")
      `CHECK(first_n == 1, "write: B latency is 1 cycle")
    end
  endtask

  // Read: AR raised after ar_dly cycles, RREADY held low for r_dly cycles
  // after AR is accepted.
  task axil_read;
    input [3:0]   addr;
    input integer ar_dly;
    input integer r_dly;
    integer t;
    integer n;
    integer first_n;
    reg ar_hs;
    reg got;
    reg [1:0]  exp_resp;
    reg [1:0]  held_resp;
    reg [31:0] exp_data;
    reg [31:0] held_data;
    begin
      exp_resp  = addr_mapped(addr[1:0]) ? OKAY : SLVERR;
      exp_data  = 32'h0000_0000;
      held_resp = 2'b00;
      held_data = 32'h0000_0000;
      ar_hs = 1'b0;
      t = 0;
      while (!ar_hs) begin
        @(negedge aclk);
        arvalid = (t >= ar_dly);
        araddr  = addr;
        rready  = 1'b0;
        #4;
        ar_hs = arvalid && arready;
        if (ar_hs)
          exp_data = addr_mapped(addr[1:0]) ? model[addr[3:2]] : 32'h0000_0000;
        `CHECK_EQ(rvalid, 1'b0, "read: no R before AR is accepted")
        @(posedge aclk);
        t = t + 1;
        if (!ar_hs && (t > 50)) begin
          `CHECK(1'b0, "read: AR not accepted within 50 cycles")
          ar_hs = 1'b1;
        end
      end
      r_accept_cycles = t;

      n = 0;
      first_n = 0;
      got = 1'b0;
      while (!got) begin
        @(negedge aclk);
        n = n + 1;
        arvalid = 1'b0;
        rready  = (n > r_dly);
        #4;
        if (rvalid) begin
          if (first_n == 0) begin
            first_n   = n;
            held_resp = rresp;
            held_data = rdata;
            `CHECK_EQ(rresp, exp_resp, "read: RRESP")
            `CHECK_EQ(rdata, exp_data, "read: RDATA")
          end else begin
            `CHECK_EQ(rresp, held_resp, "read: RRESP holds while R waits")
            `CHECK_EQ(rdata, held_data, "read: RDATA holds while R waits")
          end
          `CHECK_EQ(arready, 1'b0, "read: AR not accepted while R is pending")
          if (rready) got = 1'b1;
        end else if (first_n != 0) begin
          `CHECK(1'b0, "read: RVALID dropped before RREADY")
          got = 1'b1;
        end
        @(posedge aclk);
        if (!got && (n > 50)) begin
          `CHECK(1'b0, "read: no R within 50 cycles")
          got = 1'b1;
        end
      end
      `CHECK((first_n >= 1) && (first_n <= 2), "read: R latency at most 2 cycles")
      `CHECK(first_n == 1, "read: R latency is 1 cycle")
    end
  endtask

  task read_all;
    begin
      axil_read(4'h0, 0, 0);
      axil_read(4'h4, 0, 0);
      axil_read(4'h8, 0, 0);
      axil_read(4'hC, 0, 0);
    end
  endtask

  initial begin
    if (!$value$plusargs("nirmaan_nonce=%s", nonce)) nonce = {(8*64){1'b0}};
    reset_model;

    // 1. Reset values [AXIL-RESET]
    apply_reset(3);
    read_all;

    // 2. Write then read every register (AW and W together)
    axil_write(4'h0, 32'h0123_4567, 4'hF, 0, 0, 0);
    axil_write(4'h4, 32'h89AB_CDEF, 4'hF, 0, 0, 0);
    axil_write(4'h8, 32'hFEDC_BA98, 4'hF, 0, 0, 0);
    axil_write(4'hC, 32'h7654_3210, 4'hF, 0, 0, 0);
    read_all;

    // 3. AW/W ordering [AXIL-ORDER]
    axil_write(4'h4, 32'h1111_2222, 4'hF, 0, 3, 0);  // AW 3 cycles before W
    axil_read(4'h4, 0, 0);
    axil_write(4'h8, 32'h3333_4444, 4'hF, 2, 0, 0);  // W 2 cycles before AW
    axil_read(4'h8, 0, 0);
    axil_write(4'hC, 32'h5555_6666, 4'hF, 1, 1, 0);  // both together after idle
    axil_read(4'hC, 0, 0);
    axil_write(4'h0, 32'h7777_8888, 4'hF, 0, 1, 0);  // AW 1 cycle before W
    axil_read(4'h0, 0, 0);
    axil_write(4'h4, 32'h9999_AAAA, 4'hF, 1, 0, 0);  // W 1 cycle before AW
    axil_read(4'h4, 0, 0);

    // 4. Byte enables [AXIL-WSTRB]
    axil_write(4'h8, 32'hAABB_CCDD, 4'b0101, 0, 0, 0);
    axil_read(4'h8, 0, 0);
    axil_write(4'h8, 32'hEEFF_0011, 4'b1010, 0, 0, 0);
    axil_read(4'h8, 0, 0);
    axil_write(4'h4, 32'hDEAD_BEEF, 4'b1000, 0, 0, 0);
    axil_read(4'h4, 0, 0);
    axil_write(4'h4, 32'hDEAD_BEEF, 4'b0001, 2, 0, 0);
    axil_read(4'h4, 0, 0);
    axil_write(4'h0, 32'hFFFF_FFFF, 4'b0000, 0, 0, 0);  // empty strobe: no change, OKAY
    axil_read(4'h0, 0, 0);
    axil_write(4'hC, 32'h0000_0000, 4'b0110, 0, 2, 0);
    axil_read(4'hC, 0, 0);

    // 5. B and R back-pressure
    axil_write(4'h0, 32'hCAFE_F00D, 4'hF, 0, 0, 5);
    axil_read(4'h0, 0, 6);
    axil_write(4'hC, 32'h0BAD_F00D, 4'hF, 2, 0, 3);
    axil_read(4'hC, 1, 4);

    // 6. Back-to-back transactions [AXIL-B2B]
    axil_write(4'h4, 32'h0000_0004, 4'hF, 0, 0, 0);
    axil_write(4'h8, 32'h0000_0008, 4'hF, 0, 0, 0);
    `CHECK(w_accept_cycles == 1, "B2B: next write accepted in the cycle after B was taken")
    axil_write(4'hC, 32'h0000_000C, 4'hF, 0, 0, 0);
    `CHECK(w_accept_cycles == 1, "B2B: third write accepted in the cycle after B was taken")
    axil_read(4'h4, 0, 0);
    axil_read(4'h8, 0, 0);
    `CHECK(r_accept_cycles == 1, "B2B: next read accepted in the cycle after R was taken")
    axil_read(4'hC, 0, 0);
    `CHECK(r_accept_cycles == 1, "B2B: third read accepted in the cycle after R was taken")

    // 7. SLVERR policy for unmapped (misaligned) addresses [AXIL-SLVERR]
    axil_write(4'h5, 32'hFFFF_FFFF, 4'hF, 0, 0, 0);
    axil_write(4'hE, 32'hFFFF_FFFF, 4'hF, 1, 0, 2);
    axil_write(4'h1, 32'h1234_5678, 4'b0011, 0, 2, 0);
    axil_write(4'hB, 32'h8765_4321, 4'hF, 0, 0, 0);
    read_all;                          // no register changed
    axil_read(4'h6, 0, 0);
    axil_read(4'hD, 0, 3);
    axil_read(4'h3, 2, 0);
    axil_read(4'hF, 0, 0);

    // 8. A read and a write on the same clock (different registers)
    fork
      axil_write(4'h4, 32'hA1A2_A3A4, 4'hF, 0, 0, 0);
      axil_read(4'h8, 0, 0);
    join
    fork
      axil_write(4'hC, 32'hB1B2_B3B4, 4'hF, 1, 0, 2);
      axil_read(4'h0, 0, 3);
    join
    fork
      axil_write(4'h7, 32'hC1C2_C3C4, 4'hF, 0, 0, 1);
      axil_read(4'hC, 0, 0);
    join
    read_all;

    // 9. Reset during traffic: a half-accepted AW is discarded [AXIL-RESET]
    @(negedge aclk);
    awaddr  = 4'h4;
    awvalid = 1'b1;
    wvalid  = 1'b0;
    bready  = 1'b0;
    #4;
    `CHECK_EQ(awready, 1'b1, "mid-reset: AW accepted before reset")
    @(posedge aclk);
    apply_reset(2);
    read_all;                          // registers back to zero
    axil_write(4'h8, 32'h1234_5678, 4'hF, 4, 0, 0);  // W first: stale AW would fire early
    read_all;

    // 10. Reset during traffic: a half-accepted W is discarded
    @(negedge aclk);
    wdata   = 32'hFFFF_FFFF;
    wstrb   = 4'hF;
    wvalid  = 1'b1;
    awvalid = 1'b0;
    #4;
    `CHECK_EQ(wready, 1'b1, "mid-reset: W accepted before reset")
    @(posedge aclk);
    apply_reset(2);
    read_all;
    axil_write(4'h0, 32'h0F0F_0F0F, 4'hF, 0, 3, 0);  // AW first: stale W would fire early
    read_all;

    finished = 1'b1;
    $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed);
    $finish;
  end

  // Watchdog: a hung handshake ends the run as a failure.
  initial begin
    #200000;
    if (!finished) begin
      $error("FAIL: simulation timeout");
      $display("NIRMAAN-SIM %0s %0d passed, %0d failed", nonce, passed, failed + 1);
      $finish;
    end
  end

endmodule

`default_nettype wire
